class PriceCalculator {
   // reads only Customer's fields, does Customer's work outside Customer
+  loyaltyDiscount(c: Customer): number {
+    if (c.tier === 'gold') return c.lifetimeSpend * 0.1;
+    if (c.tier === 'silver') return c.lifetimeSpend * 0.05;
+    return 0;
+  }

   // legitimately coordinates several objects, each doing its own work
   finalPrice(cart: Cart, c: Customer, tax: TaxPolicy): number {
     const base = cart.subtotal();
     const discount = this.loyaltyDiscount(c);
     return tax.applyTo(base - discount);
   }
 }
